
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_pjs18_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_pjs18", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.467081410800928e+00, -4.374361386854588e+00, -4.244498778364996e+00, -4.064735132566501e+00, -3.820058278785281e+00, -3.494999181854217e+00, -3.077862900569314e+00, -2.568258509807517e+00, -1.986655882344917e+00, -1.377593275071466e+00, -7.951657164609414e-01, -4.591862023107681e-01, -4.471610170800165e-01, -3.420833764438436e-01, -1.966518806478578e-01, -7.378439783495482e-02, -1.296914240728964e-02, -6.819875780387220e-04, -7.326141062465289e-06, -1.029207435356347e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


